{
  "name": "loss_rankgap_tanh_advantage",
  "intuition": "Instead of modeling pairwise preference with a margin-based logitsigmoid, this loss uses the smooth bounded tanh function applied to a normalized rank gap weighted advantage difference, promoting robust ranking without relying on strict margins.",
  "pseudocode": "rank_gap = normalized_rank(lpw) - normalized_rank(lpl)\nadv_diff = advantage_w - advantage_l\nscaled = tanh(beta * rank_gap * adv_diff)\nloss = mean(weight * (1 - scaled))",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["sub", "tanh", "mean", "mul", "add"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    beta = float(extra.get('beta', extra.get('hyperparams', {}).get('beta', 5.0)))\n    rank_w = (lpw - lpw.mean()) / (lpw.std() + 1e-8)\n    rank_l = (lpl - lpl.mean()) / (lpl.std() + 1e-8)\n    rank_gap = rank_w - rank_l\n    adv_diff = advantage_w - advantage_l\n    scaled = ops.tanh(beta * rank_gap * adv_diff)\n    loss = 1 - scaled\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()"
}

{
  "name": "pairwise_preference_margin",
  "intuition": "This loss encourages the model to assign higher log probabilities to preferred options. By computing the difference between the 'better' and 'worse' log probabilities scaled by a margin, it promotes ranking accuracy. The pairwise comparison aligns with RL4CO goals by directly optimizing relative preferences, which are critical in cost-sensitive decision making.",
  "pseudocode": "loss = mean( relu( margin + log_prob_l - log_prob_w ) )",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "ranking",
    "link_family": "margin",
    "agg_family": "mean",
    "constraint_family": "pairwise",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "relu"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    margin = float(extra.get(\"margin\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    weight = batch[\"weight\"]\n    cost_gap = batch.get(\"cost_gap\", None)\n    diff = log_prob_l - log_prob_w\n    scaled_diff = margin + diff\n    loss_per_pair = ops.relu(ops.add(scaled_diff, 0))  # relu(margin + log_prob_l - log_prob_w)\n    weighted_loss = loss_per_pair * weight\n    return ops.mean(weighted_loss)"
}

{
  "name": "loss_tanh_advantage_weighted",
  "intuition": "Removed unsupported 'rank_gap' key to comply with expects; replaced the modulation term by using signed advantage difference only, stabilized via tanh to keep values within [-1,1], then applied softplus and weighted mean. This preserves ranking signal with bounded, stable inputs and adaptive weighting.",
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    signal = ops.tanh(adv_l - adv_w)\n    loss_per_pair = ops.softplus(signal) * weight\n    return ops.mean(loss_per_pair)",
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "advantage_w",
      "advantage_l"
    ]
  }
}
